import json,re,html,pathlib
out={}
for f in ['hn-tender-alerts-comments.json','hn-stotles.json']:
  d=json.load(open('products/services/tender-intelligence/buyer-guide/raw/'+f))
  rows=[]
  for h in d.get('hits',[]):
    t=h.get('comment_text') or h.get('story_text') or ''
    t=re.sub(r'<[^>]+>',' ',html.unescape(t)); t=re.sub(r'\s+',' ',t)
    rows.append({'id':h.get('objectID'),'created':h.get('created_at'),'title':h.get('title') or h.get('story_title'),'text':t[:600]})
  out[f]={'nbHits':d.get('nbHits'),'rows':rows}
p=pathlib.Path('products/services/tender-intelligence/buyer-guide/raw/hn-extract.json');p.write_text(json.dumps(out,indent=1))
print(json.dumps(out)[:30000])
